#[test]
fn test_adaptive_encoding_garbage_collection() {
    run_scripts(&[
        ScriptTest {
            name: "out-of-band values in value tuples survive garbage collection",
            set_up_script: &[
                "create table tv (id int primary key, big text);",
                "insert into tv select i, lpad(i::text, 8, '0') || repeat('v', 19992) from generate_series(1, 3) as g(i);",
                "select dolt_commit('-Am', 'values');",
            ],
            assertions: &[
                // Doltgres-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "select dolt_gc();",
                    expected: Expected::Rows {
                        columns: &[Column("dolt_gc", INT8)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                // Doltgres-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "select count(*) from tv where length(big) = 20000;",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("3")],
                        ],
                        tag: "SELECT 1",
                    },
                    username: "postgres",
                    password: "password",
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "out-of-band values in secondary index keys survive garbage collection",
            set_up_script: &[
                "create table ti (id int primary key, big text);",
                "create index ti_big on ti (big);",
                "insert into ti select i, lpad(i::text, 8, '0') || repeat('i', 19992) from generate_series(1, 3) as g(i);",
                "select dolt_commit('-Am', 'indexed');",
            ],
            assertions: &[
                // Doltgres-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "select dolt_gc();",
                    expected: Expected::Rows {
                        columns: &[Column("dolt_gc", INT8)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                // Doltgres-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "select id from ti where big = '';",
                    expected: Expected::Rows {
                        columns: &[Column("id", INT4)],
                        rows: &[
                            &[T("2")],
                        ],
                        tag: "SELECT 1",
                    },
                    username: "postgres",
                    password: "password",
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "out-of-band values in primary keys survive garbage collection",
            set_up_script: &[
                "create table tk (big text primary key, n int);",
                "insert into tk select lpad(i::text, 8, '0') || repeat('k', 19992), i from generate_series(1, 3) as g(i);",
                "select dolt_commit('-Am', 'keys');",
            ],
            assertions: &[
                // Doltgres-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "select dolt_gc();",
                    expected: Expected::Rows {
                        columns: &[Column("dolt_gc", INT8)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                // Doltgres-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "select count(*) from tk where length(big) = 20000;",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("3")],
                        ],
                        tag: "SELECT 1",
                    },
                    username: "postgres",
                    password: "password",
                    ..A
                },
                // Doltgres-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "select count(*) from tk;",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("3")],
                        ],
                        tag: "SELECT 1",
                    },
                    username: "postgres",
                    password: "password",
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_adaptive_encoding_in_primary_keys() {
    run_scripts(&[
        ScriptTest {
            name: "out-of-band values in primary keys",
            set_up_script: &[
                "create table tk (big text primary key, n int);",
                "insert into tk select lpad(i::text, 8, '0') || repeat('k', 19992), i from generate_series(1, 3) as g(i);",
                "insert into tk values ('small', 4);",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "select count(*) from tk;",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("4")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select n, length(big) from tk order by n;",
                    expected: Expected::Rows {
                        columns: &[Column("n", INT4), Column("length", INT4)],
                        rows: &[
                            &[T("1"), T("20000")],
                            &[T("2"), T("20000")],
                            &[T("3"), T("20000")],
                            &[T("4"), T("5")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select big = '' from tk where n = 2;",
                    expected: Expected::Rows {
                        columns: &[Column("?column?", BOOL)],
                        rows: &[
                            &[T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select n from tk where big = '';",
                    expected: Expected::Rows {
                        columns: &[Column("n", INT4)],
                        rows: &[
                            &[T("2")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select n from tk order by big;",
                    expected: Expected::Rows {
                        columns: &[Column("n", INT4)],
                        rows: &[
                            &[T("1")],
                            &[T("2")],
                            &[T("3")],
                            &[T("4")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "update tk set n = 20 where big = '';",
                    expected: Expected::Tag("UPDATE 1"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "select n from tk where big = '';",
                    expected: Expected::Rows {
                        columns: &[Column("n", INT4)],
                        rows: &[
                            &[T("20")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "delete from tk where big = '';",
                    expected: Expected::Tag("DELETE 1"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "select count(*) from tk;",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("3")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                // Doltgres-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "select dolt_commit('-Am', 'out-of-band keys');",
                    expected: Expected::Tag("SELECT 1"),
                    flow: Flow::Exec,
                    ..A
                },
                ScriptTestAssertion {
                    query: "select n from tk where big = '';",
                    expected: Expected::Rows {
                        columns: &[Column("n", INT4)],
                        rows: &[
                            &[T("3")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
    run_scripts(&[
        ScriptTest {
            name: "out-of-band values in primary keys",
            set_up_script: &[
                "create table tk (big varchar primary key, n int);",
                "insert into tk select lpad(i::text, 8, '0') || repeat('k', 19992), i from generate_series(1, 3) as g(i);",
                "insert into tk values ('small', 4);",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "select count(*) from tk;",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("4")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select n, length(big) from tk order by n;",
                    expected: Expected::Rows {
                        columns: &[Column("n", INT4), Column("length", INT4)],
                        rows: &[
                            &[T("1"), T("20000")],
                            &[T("2"), T("20000")],
                            &[T("3"), T("20000")],
                            &[T("4"), T("5")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select big = '' from tk where n = 2;",
                    expected: Expected::Rows {
                        columns: &[Column("?column?", BOOL)],
                        rows: &[
                            &[T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select n from tk where big = '';",
                    expected: Expected::Rows {
                        columns: &[Column("n", INT4)],
                        rows: &[
                            &[T("2")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select n from tk order by big;",
                    expected: Expected::Rows {
                        columns: &[Column("n", INT4)],
                        rows: &[
                            &[T("1")],
                            &[T("2")],
                            &[T("3")],
                            &[T("4")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "update tk set n = 20 where big = '';",
                    expected: Expected::Tag("UPDATE 1"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "select n from tk where big = '';",
                    expected: Expected::Rows {
                        columns: &[Column("n", INT4)],
                        rows: &[
                            &[T("20")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "delete from tk where big = '';",
                    expected: Expected::Tag("DELETE 1"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "select count(*) from tk;",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("3")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                // Doltgres-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "select dolt_commit('-Am', 'out-of-band keys');",
                    expected: Expected::Tag("SELECT 1"),
                    flow: Flow::Exec,
                    ..A
                },
                ScriptTestAssertion {
                    query: "select n from tk where big = '';",
                    expected: Expected::Rows {
                        columns: &[Column("n", INT4)],
                        rows: &[
                            &[T("3")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}
